import { useCallback, useEffect, useState } from 'react';

const TOKEN_KEY = 'recouvra_token';

export const getToken = () => localStorage.getItem(TOKEN_KEY);

export function setToken(token) {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

// Calls the REST API. Throws an Error carrying the server message on any non-2xx response.
export async function api(path, { method = 'GET', body, query } = {}) {
  const url = new URL(`/api${path}`, window.location.origin);
  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== '' && value !== null && value !== undefined) url.searchParams.set(key, value);
  }

  const token = getToken();
  const response = await fetch(url, {
    method,
    headers: {
      ...(body && { 'Content-Type': 'application/json' }),
      ...(token && { Authorization: `Bearer ${token}` })
    },
    body: body && JSON.stringify(body)
  });
  const data = await response.json().catch(() => ({}));

  if (response.status === 401 && token) {
    setToken(null);
    window.dispatchEvent(new Event('auth:logout'));
  }
  if (!response.ok) {
    throw new Error(data.error || data.message || `Erreur ${response.status}`);
  }
  return data;
}

// Loads `path` and reloads whenever the path or the query changes. Pass a null path to skip the call.
export function useApi(path, query) {
  const [state, setState] = useState({ data: null, error: null, loading: Boolean(path) });
  const [version, setVersion] = useState(0);
  const key = path && `${path}?${JSON.stringify(query ?? {})}`;

  useEffect(() => {
    if (!path) return;
    let active = true;
    setState(previous => ({ ...previous, loading: true }));
    api(path, { query })
      .then(data => active && setState({ data, error: null, loading: false }))
      .catch(error => active && setState({ data: null, error: error.message, loading: false }));
    return () => { active = false; };
    // `key` captures path + query by value
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, version]);

  const reload = useCallback(() => setVersion(v => v + 1), []);
  return { ...state, reload };
}

import { useState } from 'react';

// Minimal form state: bind(name) wires an input, submit(event, action) runs the action and captures its error.
export function useForm(initialValues) {
  const [values, setValues] = useState(initialValues);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  const bind = (name) => ({
    name,
    value: values[name] ?? '',
    onChange: (event) => setValues(current => ({ ...current, [name]: event.target.value }))
  });

  async function submit(event, action) {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      await action(values);
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  return { values, setValues, bind, submit, error, busy };
}

import { sendJson } from '../utils/send.js';

export function errorHandler(err, req, res, next) {
  let error = { ...err };
  error.message = err.message;
  
  
  console.error('Error:', err);

 
  if (err.name === 'CastError') {
    const message = 'Resource not found';
    error = { message, statusCode: 404 };
  }

  
  if (err.code === 11000) {
    const field = Object.keys(err.keyPattern)[0];
    const message = `Duplicate field value: ${field}. Please use another value`;
    error = { message, statusCode: 400 };
  }

  
  if (err.name === 'ValidationError') {
    const message = Object.values(err.errors).map(val => val.message).join(', ');
    error = { message, statusCode: 400 };
  }


  if (err.name === 'JsonWebTokenError') {
    const message = 'Invalid token';
    error = { message, statusCode: 401 };
  }

  if (err.name === 'TokenExpiredError') {
    const message = 'Token expired';
    error = { message, statusCode: 401 };
  }

 
  sendJson(res, error.statusCode || 500, {
    success: false,
    error: error.message || 'Server Error'
  });
}

import mongoose from 'mongoose';

const clientSchema = new mongoose.Schema({
  name: {
    type: String,
    required: [true, 'Client name is required'],
    trim: true,
    index: true
  },
  email: {
    type: String,
    required: [true, 'Email is required'],
    lowercase: true,
    trim: true,
    match: [/^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/, 'Please provide a valid email']
  },
  phone: {
    type: String,
    required: [true, 'Phone number is required'],
    trim: true
  },
  address: {
    street: { type: String, trim: true },
    city: { type: String, trim: true },
    postalCode: { type: String, trim: true },
    country: { type: String, trim: true, default: 'France' }
  },
  company: {
    type: String,
    trim: true,
    index: true
  },
  taxId: {
    type: String,
    trim: true,
    sparse: true
  },
  notes: {
    type: String,
    trim: true
  },
  createdBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true,
    index: true
  },

  // N-N: a client is followed by several agents, an agent follows several clients
  assignedAgents: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    index: true
  }],

  totalInvoices: {
    type: Number,
    default: 0
  },
  totalPaid: {
    type: Number,
    default: 0
  },
  totalUnpaid: {
    type: Number,
    default: 0
  }
}, {
  timestamps: true,
  toJSON: { virtuals: true },
  toObject: { virtuals: true }
});

clientSchema.virtual('fullAddress').get(function() {
  const parts = [];
  if (this.address.street) parts.push(this.address.street);
  if (this.address.city) parts.push(this.address.city);
  if (this.address.postalCode) parts.push(this.address.postalCode);
  if (this.address.country) parts.push(this.address.country);
  return parts.join(', ');
});


clientSchema.virtual('outstandingBalance').get(function() {
  return this.totalUnpaid;
});


clientSchema.index({ name: 'text', company: 'text', email: 'text' });

export const Client = mongoose.model('Client', clientSchema);

import mongoose from 'mongoose';
import bcrypt from 'bcryptjs';

const userSchema = new mongoose.Schema({
  email: {
    type: String,
    required: [true, 'Email is required'],
    unique: true,
    lowercase: true,
    trim: true,
    match: [/^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/, 'Please provide a valid email']
  },
  password: {
    type: String,
    required: [true, 'Password is required'],
    minlength: [6, 'Password must be at least 6 characters']
  },
  firstName: {
    type: String,
    required: [true, 'First name is required'],
    trim: true
  },
  lastName: {
    type: String,
    required: [true, 'Last name is required'],
    trim: true
  },
  role: {
    type: String,
    enum: ['agent', 'manager', 'admin'],
    default: 'agent'
  },
  active: {
    type: Boolean,
    default: true
  }
}, {
  timestamps: true
});


userSchema.pre('save', async function(next) {

  if (!this.isModified('password')) return next();
  
  try {
    const salt = await bcrypt.genSalt(parseInt(process.env.BCRYPT_ROUNDS) || 10);
    this.password = await bcrypt.hash(this.password, salt);
    next();
  } catch (error) {
    next(error);
  }
});


userSchema.methods.comparePassword = async function(candidatePassword) {
  return await bcrypt.compare(candidatePassword, this.password);
};


userSchema.set('toJSON', {
  transform: (doc, ret) => {
    delete ret.password;
    return ret;
  }
});


userSchema.set('toObject', {
  transform: (doc, ret) => {
    delete ret.password;
    return ret;
  }
});

export const User = mongoose.model('User', userSchema);

// Status workflow of a collection action.
//
//   planned ──► completed            (terminal, requires a result)
//      │  ──► failed ──► planned     (retry, requires a future date)
//      │         └────► cancelled
//      └────► cancelled              (terminal, manager/admin only)

export const ACTION_STATUSES = ['planned', 'completed', 'failed', 'cancelled'];

export const ACTION_TRANSITIONS = Object.freeze({
  planned: ['completed', 'failed', 'cancelled'],
  failed: ['planned', 'cancelled'],
  completed: [],
  cancelled: []
});

export function allowedTransitions(status) {
  return ACTION_TRANSITIONS[status] ?? [];
}

// Returns null when the transition is allowed, otherwise { status, message } describing the refusal.
export function checkTransition({ from, to, role, result, actionDate, now = new Date() }) {
  if (!allowedTransitions(from).includes(to)) {
    return { status: 409, message: `Transition from ${from} to ${to} is not allowed` };
  }

  if ((to === 'completed' || to === 'failed') && !result?.trim()) {
    return { status: 400, message: `A result is required to mark an action as ${to}` };
  }

  if (to === 'cancelled' && role === 'agent') {
    return { status: 403, message: 'Only a manager or an admin can cancel a collection action' };
  }

  if (to === 'planned' && !(actionDate && new Date(actionDate) > now)) {
    return { status: 400, message: 'Rescheduling an action requires a future action date' };
  }

  return null;
}
